// Cliquer sur le bouton Continue Shopping
cy.get('[data-test="continue-shopping"]').should('be.visible').click();
// Vérifier Le retour à la page Produits
cy.location('pathname').should('eq', '/inventory.html');
// Vérifier que le badge conserve le nombre des deux articles.
cy.get('[data-test="shopping-cart-badge"]').should('be.visible').and('have.text', '2');
// Réouvrir le panier pour contrôler les articles conservés.
cy.get('[data-test="shopping-cart-link"]').should('be.visible').click();
// Vérifier que la page du panier est affichée de nouveau.
cy.location('pathname').should('eq', '/cart.html');
// Vérifier que les deux lignes d'articles sont toujours présentes.
cy.get('.cart_item').should('have.length', 2);
// Vérifier que le Sauce Labs Backpack est toujours dans le panier.
cy.contains('[data-test="inventory-item-name"]', 'Sauce Labs Backpack').should('be.visible');
// Vérifier que le Sauce Labs Bike Light est toujours dans le panier.
cy.contains('[data-test="inventory-item-name"]', 'Sauce Labs Bike Light').should('be.visible');
